-- Hosbah queries (MH-578 C10: team SSH key library — install matrix).

-- name: ListSSHKeyInstalls :many
-- Every server this key has ever been asked to install to, in the team.
SELECT * FROM ssh_key_installs WHERE ssh_key_id = sqlc.arg('ssh_key_id') AND team_id = sqlc.arg('team_id') ORDER BY server_id, unix_user;

-- name: ListTeamSSHKeyInstalls :many
-- Every install row of the team (all keys), for the per-server matrix.
SELECT * FROM ssh_key_installs WHERE team_id = sqlc.arg('team_id') ORDER BY ssh_key_id, server_id, unix_user;

-- name: UpsertSSHKeyInstall :one
INSERT INTO ssh_key_installs (team_id, ssh_key_id, server_id, unix_user, status, last_operation_id, last_error, installed_at, removed_at)
VALUES (sqlc.arg('team_id'), sqlc.arg('ssh_key_id'), sqlc.arg('server_id'), sqlc.arg('unix_user'), sqlc.arg('status'),
    sqlc.narg('last_operation_id'), sqlc.arg('last_error'), sqlc.narg('installed_at'), sqlc.narg('removed_at'))
ON CONFLICT (ssh_key_id, server_id, unix_user) DO UPDATE SET
    status = excluded.status, last_operation_id = excluded.last_operation_id, last_error = excluded.last_error,
    installed_at = coalesce(excluded.installed_at, ssh_key_installs.installed_at),
    removed_at = coalesce(excluded.removed_at, ssh_key_installs.removed_at), updated_at = now()
RETURNING *;
